<div class="section-toolbar"><div class="tabs"><a class="<?= empty($_GET['status']) ? 'active' : '' ?>" href="<?= e(url('inventory')) ?>">All vehicles</a><?php foreach (['Available', 'Sold', 'Reserved'] as $status): ?><a class="<?= ($_GET['status'] ?? '') === $status ? 'active' : '' ?>" href="<?= e(url('inventory', ['status' => $status])) ?>"><?= e($status) ?></a><?php endforeach; ?></div><div class="toolbar-actions"><a class="button primary" href="<?= e(url('vehicle-new')) ?>">+ Add vehicle</a></div></div>
<section class="panel"><form class="filter-bar" method="get"><input type="hidden" name="r" value="inventory"><input type="hidden" name="status" value="<?= e($_GET['status'] ?? '') ?>"><div class="search-field"><label class="sr-only" for="search">Search vehicles</label><input id="search" name="q" placeholder="Search ID, brand, or model…" value="<?= e($_GET['q'] ?? '') ?>"></div><div><label class="sr-only" for="search-mode">Search mode</label><select name="search_mode" id="search-mode"><option value="text">ID, brand, or model</option value="id"<?= selected($_GET['search_mode'] ?? '', 'id') ?>>Exact vehicle ID</option></select></div><div><label class="sr-only" for="sort">Sort by</label><select name="sort" id="sort"><?php foreach (['Vehicle_ID' => 'Vehicle ID', 'Price' => 'Price', 'Brand_Name' => 'Brand', 'Model' => 'Model', 'Year' => 'Year'] as $key => $label): ?><option value="<?= e($key) ?>"<?= selected($_GET['sort'] ?? 'Vehicle_ID', $key) ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div><label class="sr-only" for="direction">Sort direction</label><select name="direction" id="direction"><option value="desc"<?= selected($_GET['direction'] ?? 'desc', 'desc') ?>>Descending</option><option value="asc"<?= selected($_GET['direction'] ?? '', 'asc') ?>>Ascending</option></select></div><button class="button secondary" type="submit">Apply</button><a class="text-link" href="<?= e(url('inventory')) ?>">Reset</a></form>
<div class="vehicle-grid">
<?php foreach ($rows as $v): $photos = \NVRO\Services\VehiclePhotos::paths($v); ?>
<article class="vehicle-card">
    <a class="vehicle-cover" href="<?= e(url('vehicle', ['id' => $v['Vehicle_ID']])) ?>" aria-label="View <?= e($v['Brand_Name'] . ' ' . $v['Model']) ?>">
        <?php if ($photos): ?><img src="<?= e($photos[0]) ?>" alt="<?= e($v['Brand_Name'] . ' ' . $v['Model']) ?>" loading="lazy"><?php else: ?><span class="photo-placeholder"><svg viewBox="0 0 48 36" aria-hidden="true"><rect x="3" y="3" width="42" height="30" rx="4"/><circle cx="15" cy="13" r="3"/><path d="m5 29 12-10 8 6 8-12 10 16"/></svg>No photo yet</span><?php endif; ?>
        <?= badge($v['Availability_Status']) ?>
        <?php if (count($photos) > 1): ?><span class="photo-count"><?= count($photos) ?> photos</span><?php endif; ?>
    </a>
    <div class="vehicle-card-body"><small class="muted">#<?= e($v['Vehicle_ID']) ?> · <?= e($v['Year']) ?></small><h2><a class="vehicle-name" href="<?= e(url('vehicle', ['id' => $v['Vehicle_ID']])) ?>"><?= e($v['Brand_Name'] . ' ' . $v['Model']) ?></a></h2><p class="vehicle-card-specs"><?= e($v['Color'] . ' · ' . $v['Transmission'] . ' · ' . $v['Fuel_Type']) ?></p><p class="vehicle-card-price"><?= money($v['Price']) ?></p><div class="vehicle-card-actions"><a class="text-link" href="<?= e(url('vehicle', ['id' => $v['Vehicle_ID']])) ?>">View details →</a><a class="button secondary small" href="<?= e(url('vehicle-edit', ['id' => $v['Vehicle_ID']])) ?>">Edit</a></div></div>
<?php if ($v['Availability_Status'] !== 'Sold'): ?><form class="card-sale-action" method="post" action="<?= e(url('vehicle-sold', ['id' => $v['Vehicle_ID']])) ?>" data-confirm="Mark this vehicle as sold?"><?= csrf() ?><button class="button sold-button small" type="submit">Mark as sold</button></form><?php endif; ?>
</article>
<?php endforeach; ?>
</div>
<?php if (!$rows): ?><div class="empty-state"><h3>No vehicles found</h3><p>Add a vehicle or adjust your search and filters.</p><a class="button primary" href="<?= e(url('vehicle-new')) ?>">+ Add vehicle</a></div><?php endif; ?>
